#!/usr/bin/env bash
# ==============================================================================
# Script: Generate-DFIRHtmlReport.sh
# Description: Generates standalone interactive HTML Forensic Report for Linux
# Documentation: Parses collected CSV files and forensic evidence generated by DFIR-Script.sh
#                and modular acquisition scripts, generating a standalone, interactive
#                dark-mode HTML dashboard with metric cards, search, filters,
#                AppArmor/SELinux denials, eBPF programs, Desktop/Trash artifacts,
#                Cloud metadata, C2 Tunnels, Developer ecosystem, and threat alerts.
# Author: Bellk0ruh
# License: BSD 3-Clause
# ==============================================================================

set -uo pipefail

EVIDENCE_PATH="${1:-}"
OUTPUT_HTML="${2:-}"

# Automatically resolve the most recent DFIR folder if none specified
if [ -z "$EVIDENCE_PATH" ]; then
    EVIDENCE_PATH=$(ls -td DFIR-* 2>/dev/null | head -n 1 || echo "")
fi

if [ -z "$EVIDENCE_PATH" ] || [ ! -d "$EVIDENCE_PATH" ]; then
    echo "Usage: $0 [DFIR_Evidence_Folder] [Output_Report.html]" >&2
    exit 1
fi

HOSTNAME_VAL="Unknown-Host"
if [ -f "${EVIDENCE_PATH}/manifest.json" ]; then
    HOSTNAME_VAL=$(grep -oP '"hostname":\s*"\K[^"]+' "${EVIDENCE_PATH}/manifest.json" 2>/dev/null || echo "Unknown-Host")
fi

TIMESTAMP_VAL=$(date +"%Y%m%d_%H%M%S")
[ -z "$OUTPUT_HTML" ] && OUTPUT_HTML="${EVIDENCE_PATH}/DFIR-Report-${HOSTNAME_VAL}-${TIMESTAMP_VAL}.html"

CSV_DIR="${EVIDENCE_PATH}/CSV_Results"

echo "Generating standalone HTML forensic report..."
echo "Source Directory: ${EVIDENCE_PATH}"
echo "Output Report   : ${OUTPUT_HTML}"

# Metric counts
proc_count=$( [ -f "${CSV_DIR}/Processes.csv" ] && tail -n +2 "${CSV_DIR}/Processes.csv" | wc -l || echo "0" )
sock_count=$( [ -f "${CSV_DIR}/OpenSockets.csv" ] && tail -n +2 "${CSV_DIR}/OpenSockets.csv" | wc -l || echo "0" )
pers_count=$( [ -f "${CSV_DIR}/PersistenceSummary.csv" ] && tail -n +2 "${CSV_DIR}/PersistenceSummary.csv" | wc -l || echo "0" )
user_count=$( [ -f "${CSV_DIR}/LocalUsers.csv" ] && tail -n +2 "${CSV_DIR}/LocalUsers.csv" | wc -l || echo "0" )
suid_count=$( [ -f "${CSV_DIR}/SUIDBinaries.csv" ] && tail -n +2 "${CSV_DIR}/SUIDBinaries.csv" | wc -l || echo "0" )
ai_count=$( [ -f "${CSV_DIR}/AIToolsDetected.csv" ] && tail -n +2 "${CSV_DIR}/AIToolsDetected.csv" | wc -l || echo "0" )
device_count=$( [ -f "${CSV_DIR}/ConnectedDevices.csv" ] && tail -n +2 "${CSV_DIR}/ConnectedDevices.csv" | wc -l || echo "0" )
container_count=$( [ -f "${CSV_DIR}/Containers.csv" ] && tail -n +2 "${CSV_DIR}/Containers.csv" | wc -l || echo "0" )
tunnel_count=$( [ -f "${CSV_DIR}/TunnelingArtifacts.csv" ] && tail -n +2 "${CSV_DIR}/TunnelingArtifacts.csv" | wc -l || echo "0" )
ebpf_count=$( [ -f "${CSV_DIR}/EBPFPrograms.csv" ] && tail -n +2 "${CSV_DIR}/EBPFPrograms.csv" | wc -l || echo "0" )
dev_count=$( [ -f "${CSV_DIR}/DeveloperEcosystem.csv" ] && tail -n +2 "${CSV_DIR}/DeveloperEcosystem.csv" | wc -l || echo "0" )

# Suspicious indicator counts
deleted_exe_count=$( [ -f "${CSV_DIR}/DeletedRunningBinaries.csv" ] && tail -n +2 "${CSV_DIR}/DeletedRunningBinaries.csv" | wc -l || echo "0" )
memfd_count=$( [ -f "${CSV_DIR}/MemfdExecutions.csv" ] && tail -n +2 "${CSV_DIR}/MemfdExecutions.csv" | wc -l || echo "0" )
gtfo_count=$( [ -f "${CSV_DIR}/SUIDBinaries.csv" ] && grep -c ',"True"' "${CSV_DIR}/SUIDBinaries.csv" || echo "0" )
susp_cmd_count=$( [ -f "${CSV_DIR}/CommandHistory.csv" ] && grep -c ',"True"' "${CSV_DIR}/CommandHistory.csv" || echo "0" )
aa_denial_count=$( [ -f "${CSV_DIR}/AppArmorDenials.csv" ] && tail -n +2 "${CSV_DIR}/AppArmorDenials.csv" | wc -l || echo "0" )
se_denial_count=$( [ -f "${CSV_DIR}/SELinuxDenials.csv" ] && tail -n +2 "${CSV_DIR}/SELinuxDenials.csv" | wc -l || echo "0" )
total_alerts=$((deleted_exe_count + memfd_count + gtfo_count + susp_cmd_count + aa_denial_count + se_denial_count))

# Helper function to convert CSV into filterable HTML table
csv_to_html_table() {
    local csv_file="$1"
    local table_id="$2"
    
    if [ ! -f "$csv_file" ] || [ "$(wc -l < "$csv_file")" -le 1 ]; then
        echo "<p class='no-data'>No data available for this section.</p>"
        return
    fi
    
    echo "<div class='table-responsive'>"
    echo "<table class='dfir-table' id='${table_id}'>"
    echo "<thead><tr>"
    
    # Table headers
    head -n 1 "$csv_file" | sed 's/\r//g' | awk -F',' '{
        for (i=1; i<=NF; i++) {
            gsub(/^"|"$/, "", $i);
            print "<th>" $i "</th>";
        }
    }'
    echo "</tr></thead><tbody>"
    
    # Table rows
    tail -n +2 "$csv_file" | head -n 500 | sed 's/\r//g' | while IFS= read -r row || [ -n "$row" ]; do
        echo "<tr>"
        # Parse CSV line respecting double quotes
        echo "$row" | awk -v FPAT='([^,]+)|(\"[^\"]+\")' '{
            for (i=1; i<=NF; i++) {
                val = $i;
                gsub(/^"|"$/, "", val);
                gsub(/</, "\\&lt;", val);
                gsub(/>/, "\\&gt;", val);
                
                # Highlighting suspicious values
                cls = "";
                if (val == "True" || val == "CRITICAL" || val == "HIGH" || val == "DENIED" || val == "UNAUTHENTICATED_PUBLIC_EXPOSURE" || val == "RUNNING" || val == "SUSPICIOUS_PROBE_TYPE" || val == "CODE_EXECUTION_HOOK") {
                    cls = "badge-danger";
                } else if (val == "MEDIUM" || val == "DETECTED" || val == "WARNING" || val == "CONFIG_FOUND" || val == "ACTIVE" || val == "AUTH_TOKEN_PRESENT") {
                    cls = "badge-warning";
                }
                
                if (cls != "") {
                    print "<td><span class=\"" cls "\">" val "</span></td>";
                } else {
                    print "<td>" val "</td>";
                }
            }
        }'
        echo "</tr>"
    done
    
    echo "</tbody></table></div>"
}

# ------------------------------------------------------------------------------
# Assemble HTML Document
# ------------------------------------------------------------------------------
cat <<EOF > "$OUTPUT_HTML"
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
