        * { box-sizing: border-box; margin: 0; padding: 0; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Oxygen, Ubuntu, Cantarell, sans-serif; }
        body { background-color: var(--bg-main); color: var(--text-main); line-height: 1.6; padding: 24px; }
        
        .header { display: flex; justify-content: space-between; align-items: center; padding-bottom: 20px; border-bottom: 1px solid var(--border-color); margin-bottom: 24px; flex-wrap: wrap; gap: 15px; }
        .header h1 { font-size: 24px; color: #ffffff; display: flex; align-items: center; gap: 10px; }
        .header h1 span { color: var(--accent-cyan); }
        .header .meta { font-size: 13px; color: var(--text-muted); text-align: right; }
        
        /* Metric Cards Grid */
        .metrics-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(150px, 1fr)); gap: 14px; margin-bottom: 28px; }
        .card { background-color: var(--bg-card); border: 1px solid var(--border-color); border-radius: 8px; padding: 14px; display: flex; flex-direction: column; transition: transform 0.2s, border-color 0.2s; }
        .card:hover { transform: translateY(-2px); border-color: var(--accent-cyan); }
        .card .title { font-size: 11px; font-weight: 600; text-transform: uppercase; color: var(--text-muted); margin-bottom: 6px; }
        .card .value { font-size: 22px; font-weight: 700; color: #ffffff; }
        .card.alert-card .value { color: var(--accent-red); }
        
        /* Search & Filter Bar */
        .controls-bar { display: flex; gap: 15px; margin-bottom: 20px; flex-wrap: wrap; }
        .search-box { flex: 1; min-width: 250px; background-color: var(--bg-card); border: 1px solid var(--border-color); border-radius: 6px; padding: 10px 14px; color: #ffffff; font-size: 14px; outline: none; }
        .search-box:focus { border-color: var(--accent-cyan); }
        
        /* Navigation Tabs */
        .tabs { display: flex; gap: 6px; border-bottom: 1px solid var(--border-color); margin-bottom: 24px; overflow-x: auto; padding-bottom: 4px; }
        .tab-btn { background: none; border: none; padding: 8px 12px; color: var(--text-muted); font-size: 12px; font-weight: 600; cursor: pointer; border-radius: 6px; transition: all 0.2s; white-space: nowrap; }
        .tab-btn:hover { background-color: var(--bg-hover); color: var(--text-main); }
        .tab-btn.active { background-color: var(--bg-hover); color: var(--accent-cyan); border-bottom: 2px solid var(--accent-cyan); }
        
        /* Tab Content */
        .tab-pane { display: none; }
        .tab-pane.active { display: block; animation: fadeIn 0.3s ease; }
        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
        
        /* Tables */
        .table-responsive { overflow-x: auto; background-color: var(--bg-card); border: 1px solid var(--border-color); border-radius: 8px; margin-bottom: 24px; }
        .dfir-table { width: 100%; border-collapse: collapse; text-align: left; font-size: 13px; }
        .dfir-table th { background-color: #1c2128; color: var(--text-muted); padding: 12px 14px; font-weight: 600; border-bottom: 1px solid var(--border-color); }
        .dfir-table td { padding: 10px 14px; border-bottom: 1px solid var(--border-color); color: var(--text-main); word-break: break-all; }
        .dfir-table tr:hover { background-color: var(--bg-hover); }
        
        /* Badges */
        .badge-danger { background-color: rgba(248, 81, 73, 0.15); color: var(--accent-red); padding: 3px 8px; border-radius: 12px; font-weight: 600; font-size: 11px; border: 1px solid rgba(248, 81, 73, 0.4); }
        .badge-warning { background-color: rgba(210, 153, 34, 0.15); color: var(--accent-yellow); padding: 3px 8px; border-radius: 12px; font-weight: 600; font-size: 11px; border: 1px solid rgba(210, 153, 34, 0.4); }
        .badge-info { background-color: rgba(88, 166, 255, 0.15); color: var(--accent-cyan); padding: 3px 8px; border-radius: 12px; font-weight: 600; font-size: 11px; }
        
        .section-title { font-size: 18px; color: #ffffff; margin-bottom: 14px; display: flex; align-items: center; gap: 8px; }
        .no-data { padding: 20px; color: var(--text-muted); font-style: italic; text-align: center; }
        
        /* Footer */
        .footer { margin-top: 40px; padding-top: 15px; border-top: 1px solid var(--border-color); text-align: center; font-size: 12px; color: var(--text-muted); }
    </style>
</head>
<body>

    <div class="header">
        <div>
            <h1><span>⚡ DFIR Bash</span> Incident Response Report</h1>
